-- 05_comms.sql — generated by scripts/seed/playground/generate.js; edit that, not this.
-- Announcements, reads and acks, message threads, AI summaries.
BEGIN;

CREATE OR REPLACE FUNCTION pg_temp.rnd(k text) RETURNS float8 LANGUAGE sql IMMUTABLE AS
  $$ SELECT ('x' || substr(md5(k), 1, 12))::bit(48)::bigint / 281474976710656.0 $$;
CREATE OR REPLACE FUNCTION pg_temp.at(d date, t time) RETURNS timestamptz LANGUAGE sql STABLE AS
  $$ SELECT (d + t) AT TIME ZONE 'America/Toronto' $$;
CREATE OR REPLACE FUNCTION pg_temp.sid(k text) RETURNS uuid LANGUAGE sql IMMUTABLE AS
  $$ SELECT md5('playground-seed:' || k)::uuid $$;

-- The year, its active term, today (Toronto) and the school days so far.
CREATE TEMP TABLE ctx ON COMMIT DROP AS
SELECT y.school_year_id AS year_id, y.school_id, (now() AT TIME ZONE 'America/Toronto')::date AS today,
       t.term_id, t.name AS term_name, t.start_date AS term_start, t.end_date AS term_end,
       t.start_date - (EXTRACT(ISODOW FROM t.start_date)::int - 1) AS term_monday
  FROM school_years y
  JOIN terms t ON t.school_year_id = y.school_year_id AND t.is_active
 WHERE y.school = 'PLAYGROUND' AND y.label = '2026-2027';
DO $$ BEGIN IF (SELECT count(*) FROM ctx) <> 1 THEN RAISE EXCEPTION 'PLAYGROUND 2026-2027 with one active term not found: run 01 first'; END IF; END $$;
CREATE TEMP TABLE school_days ON COMMIT DROP AS
SELECT d::date AS day
  FROM ctx, generate_series(ctx.term_start, ctx.term_end, interval '1 day') d
 WHERE EXTRACT(ISODOW FROM d) < 6
   AND NOT EXISTS (SELECT 1 FROM school_calendar_events e
                    WHERE e.school = 'PLAYGROUND' AND e.school_year_id = ctx.year_id AND e.is_school_closed
                      AND d::date BETWEEN e.start_date AND COALESCE(e.end_date, e.start_date));

CREATE TEMP TABLE ann ON COMMIT DROP AS
SELECT v.id::uuid AS announcement_id, v.scope, v.class_id::uuid, v.grade, v.title, v.body, v.author_id::uuid, v.author_role,
       LEAST(pg_temp.at(ctx.today - v.days_ago, '08:20'), now() - interval '10 minutes') AS published_at, v.ack, v.pin_days, v.key
  FROM (VALUES
  ('2829bb92-39a7-510f-f1c9-3efa45077320', 'school', NULL, NULL, 'Welcome to the 2026–2027 school year!', 'Assalamu alaikum and welcome back! We are excited to start a new year together. Please check the calendar for important dates and make sure your contact information is up to date in the parent portal.', 'a01a2e53-2ed0-fbfe-51b2-f1b10c54f7af', 'ADMIN', 48, FALSE, NULL, 'welcome'),
  ('b29a0d0c-91be-07dc-c32d-0251ba3b9d98', 'school', NULL, NULL, 'Picture Day — Thursday, September 24', 'Picture Day is next Thursday. Students should wear full uniform. Order forms went home in backpacks today; online ordering is also available.', 'a12d71dc-d647-3997-dcd2-ec05ec39a2b1', 'ADMIN', 33, FALSE, NULL, 'picture-day'),
  ('c9251ede-aee8-9c85-4e59-8a8afe314136', 'school', NULL, NULL, 'Long weekend: PA Day and Thanksgiving', 'Reminder that there is no school on Friday, October 9 (PA Day) or Monday, October 12 (Thanksgiving). Classes resume Tuesday, October 13. Enjoy the long weekend!', 'a01a2e53-2ed0-fbfe-51b2-f1b10c54f7af', 'ADMIN', 14, FALSE, NULL, 'thanksgiving'),
  ('71edae31-8406-e474-6a1a-4b7856c471c6', 'school', NULL, NULL, 'Fall Fun Fair — volunteers needed', 'Our Fall Fun Fair is on Friday, October 30. We need parent volunteers for the game booths and the bake sale. Reply to this post or contact the office if you can help for an hour.', '0efacc5e-587c-ff55-52c4-fe346ce752dc', 'ADMIN', 5, FALSE, NULL, 'fun-fair'),
  ('50e6d5e0-4234-9d48-8493-9a93e4d2cdbe', 'school', NULL, NULL, 'Parent–teacher interviews: booking opens November 2', 'Interviews take place on Thursday, November 19 (evening) and Friday, November 20. Booking opens in the parent portal on November 2. Please press "Got it" so we know you have seen this.', 'a01a2e53-2ed0-fbfe-51b2-f1b10c54f7af', 'ADMIN', 1, TRUE, 31, 'interviews'),
  ('1621d401-2d74-44b9-d4fb-f4a9fdd313ba', 'school', NULL, NULL, 'Hot lunch orders due Friday', 'November hot lunch orders are due this Friday. Menus are posted on the office door and in the parent portal.', 'a12d71dc-d647-3997-dcd2-ec05ec39a2b1', 'ADMIN', 0, FALSE, NULL, 'hot-lunch'),
  ('5597112b-46b1-e166-c110-b048dbaf693b', 'grade', NULL, '5', 'Grade 5 trip to the Royal Ontario Museum — Friday, Oct 23', 'Grade 5 is visiting the ROM this Friday as part of our Science unit. Please return the signed permission form and pack a nut-free lunch. Press "Got it" once you have read this.', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 7, TRUE, NULL, 'g5-trip'),
  ('e3d9daad-21d1-247f-4381-c1ec4f65e146', 'grade', NULL, '8', 'Grade 8 graduation committee — first meeting', 'The graduation committee meets every second Wednesday at lunch, starting next week. All Grade 8 students are welcome to join.', '492150b0-571a-1d04-bc97-007b9e24194d', 'TEACHER', 12, FALSE, NULL, 'g8-grad'),
  ('64c65b10-db06-7747-ca08-b5ffc32256ef', 'grade', NULL, 'SK', 'SK pajama & book day this Friday', 'Friday is pajama and book day in SK! Send your child in comfy pajamas with a favourite book to share.', '76b52775-6d0c-4da4-f780-bdb155d54ffa', 'TEACHER', 1, FALSE, NULL, 'sk-pajama'),
  ('633a9aca-1a0e-bf12-f8a7-dc2baaf55c3e', 'class', '46d7f839-ba64-cb2e-8923-7b80943a8012', NULL, 'Times tables challenge starts Monday', 'Starting Monday we are doing a two-week times tables challenge. Practise for five minutes a day using the link in Classwork. Small prizes for everyone who improves!', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 11, FALSE, NULL, 'g5-math-tables'),
  ('23f3aa22-3a1e-ee9f-3171-51f23a4b3ca6', 'class', 'b0fecec9-1ac8-7da0-5664-6eccc322338c', NULL, 'Bring a leaf on Thursday', 'We are looking at real plant cells under the microscope on Thursday. Please bring one fresh leaf from home in a zip bag.', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 0, TRUE, NULL, 'g5-sci-leaf'),
  ('c9cbe0b2-768d-3de8-2ea6-8f578a926ddf', 'class', 'd261c0a4-20a0-7a64-2016-5a826e8f9f76', NULL, 'Book fair this week', 'The Scholastic book fair is in the library all week. Our class visits on Wednesday afternoon.', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 6, FALSE, NULL, 'g5-la-bookfair'),
  ('bb44c955-a34e-bf45-3628-b8a238db96be', 'class', 'f22d8b8c-3fca-ad2b-2c95-2399475bb11f', NULL, 'Unit 2 test moved to next Thursday', 'Because of the PA day, the Unit 2 test is moving to next Thursday. We will review in class on Tuesday and Wednesday.', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 4, FALSE, NULL, 'g6-math-test'),
  ('ee824938-da15-98dd-fbcc-c17221db5153', 'class', '8bbb5e75-a588-04b7-36f9-260dc01609be', NULL, 'Reading logs go home every Monday', 'Reading logs go home every Monday and come back on Friday. Please read with your child for 15 minutes each night and initial the log.', '77db6695-2c84-7c9a-392a-ada24615273a', 'TEACHER', 29, FALSE, NULL, 'g2-reading-logs'),
  ('cdb1449d-e456-d65c-1bb2-eaec345e1521', 'class', 'fa414392-c45b-a6d2-fa06-4e660fe4c440', NULL, 'Science fair proposals due November 2', 'Your science fair proposal is due November 2. Use the template in Classwork and talk to me if you need help choosing a question.', '10e5702d-d9fe-7fce-8be8-0ba4ffb45d7e', 'TEACHER', 15, FALSE, NULL, 'g7-sci-fair'),
  ('468916ae-c964-83ce-9068-2ec3f10d33fd', 'class', '66e455a1-efbe-82c3-9b05-923c34f3e426', NULL, 'Letter of the week: ب', 'This week we are learning the letter ب (baa). Ask your child to show you how it is written at the start, middle and end of a word.', 'c947d025-38eb-28f3-f837-c4bfee612489', 'TEACHER', 1, FALSE, NULL, 'g1-arabic-letter'),
  ('3214109d-99bd-35ce-2b91-92e776f789a0', 'custom', NULL, NULL, 'Math club — you are invited!', 'You have been invited to join Math Club on Tuesdays at lunch in Room 107. We will work on puzzles and get ready for the spring math contest.', '0efacc5e-587c-ff55-52c4-fe346ce752dc', 'ADMIN', 8, FALSE, NULL, 'math-club')
  ) v(id, scope, class_id, grade, title, body, author_id, author_role, days_ago, ack, pin_days, key)
  CROSS JOIN ctx;
INSERT INTO announcements (announcement_id, school, school_year_id, scope, class_id, grade, title, body, author_id, author_role,
                           published_at, pinned_until, ack_requested, send_email, created_at)
SELECT a.announcement_id, 'PLAYGROUND', ctx.year_id, a.scope, a.class_id, a.grade, a.title, a.body, a.author_id, a.author_role,
       a.published_at, CASE WHEN a.pin_days IS NOT NULL THEN ctx.today + a.pin_days END, a.ack, FALSE, a.published_at
  FROM ann a CROSS JOIN ctx;
