INSERT INTO messages (message_id, conversation_id, sender_id, sender_role, kind, body, created_at)
SELECT v.id::uuid, v.conversation_id::uuid, v.sender_id::uuid, v.sender_role, 'message', v.body, v.created_at
  FROM (VALUES
  ('a6223772-884d-8106-d7ae-46fbf415a30f', '61f69079-4699-5861-1218-8f85da201134', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Salam Ms. Saleh, Adam was at a medical appointment on Tuesday. Could you tell me what he missed in Math and Science?', now() - interval '30240 minutes'),
  ('002ebaa2-3377-0048-f5e3-66a86fada691', '61f69079-4699-5861-1218-8f85da201134', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'Wa alaikum salam! No problem. We wrote the Unit 1 test in Math, so Adam can write it on Thursday at lunch. In Science we started the matter unit — the notes are in Classwork.', now() - interval '30000 minutes'),
  ('ce004336-f6d8-ada6-8345-ca29243a118a', '61f69079-4699-5861-1218-8f85da201134', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Thank you so much, Thursday works.', now() - interval '29900 minutes'),
  ('dcd65e7c-5889-0136-4154-2504e61550ca', '1d7b043e-c8be-675b-1317-7b247299b1ed', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Hi Ms. Saleh, Adam was disappointed with his Unit 1 test. Is there anything he can do to improve before the next one?', now() - interval '2880 minutes'),
  ('8635d2df-c56b-3b5f-c42d-51abc62beda2', '1d7b043e-c8be-675b-1317-7b247299b1ed', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'Adam understood the place value questions well. Most of the marks he lost were on rounding. I would practise rounding to the nearest ten and hundred — there is a link in Classwork.', now() - interval '2700 minutes'),
  ('ada5ccf5-78e6-3cb8-290d-f9658bfd9f44', '1d7b043e-c8be-675b-1317-7b247299b1ed', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Thank you, that helps. Would a retest be possible?', now() - interval '2600 minutes'),
  ('326daa60-464c-4c70-5f94-07842f2b9ef4', '1d7b043e-c8be-675b-1317-7b247299b1ed', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Just following up on the retest question when you have a moment.', now() - interval '95 minutes'),
  ('3353b177-01c2-f75a-3fe4-938dc575683f', 'fd5bbfe7-87b8-fdbe-8680-23d854d1d09b', 'af9ffb3c-d0ad-65a1-2ead-d59cabe180f3', 'PARENT', 'Hello, Adam has been spending close to two hours a night on homework. Is that expected for Grade 5?', now() - interval '14400 minutes'),
  ('03c4d550-bdfe-b773-f72b-d7e74587d8ed', 'fd5bbfe7-87b8-fdbe-8680-23d854d1d09b', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'Thanks for letting me know. Homework should take about 40 minutes. I will check in with Adam — he may be redoing work he already finished in class.', now() - interval '14100 minutes'),
  ('0d328b7f-543b-eb4d-37b8-c0c2ed6d6575', '9d68ec66-83e9-3318-5ff6-066bb1df06ac', '0a440500-ad7b-2c0b-e985-0ec3338931a7', 'STUDENT', 'Ms. Saleh, I turned in my lab late because I was away. Is that okay?', now() - interval '9000 minutes'),
  ('db9b6186-0e5a-4d76-7fa5-f111f25a029a', '9d68ec66-83e9-3318-5ff6-066bb1df06ac', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'Yes, that is fine Adam. I left you some feedback — next time add a sentence about what surprised you.', now() - interval '8800 minutes'),
  ('5498325e-18ad-5218-c188-238e9358114d', '9d68ec66-83e9-3318-5ff6-066bb1df06ac', '0a440500-ad7b-2c0b-e985-0ec3338931a7', 'STUDENT', 'Okay thank you!', now() - interval '8700 minutes'),
  ('4c52fc39-43d0-9802-29fc-0fd7aa9c4d8c', 'aacea8dd-5614-d528-97c8-05f27c37dd02', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Hi Ms. Darwish, how is Lina doing with her reading? She says the books are too easy.', now() - interval '7200 minutes'),
  ('ba9b4e27-222c-ad81-00f0-9b16f80042e9', 'aacea8dd-5614-d528-97c8-05f27c37dd02', '77db6695-2c84-7c9a-392a-ada24615273a', 'TEACHER', 'Lina is reading very well! I moved her up a level this week, so she should bring home more challenging books now.', now() - interval '7000 minutes'),
  ('1af20ba0-2abc-4db3-002c-8ccbe4eeb544', 'aacea8dd-5614-d528-97c8-05f27c37dd02', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Wonderful, thank you!', now() - interval '6900 minutes'),
  ('fe7b1f5d-1069-305d-f2c8-0a6e07c6c819', 'dbb96945-33e6-f0e9-820f-7ead273b4bd4', '76b52775-6d0c-4da4-f780-bdb155d54ffa', 'TEACHER', 'Just a quick note: Sara has settled in beautifully. She loves the painting centre and has made two good friends.', now() - interval '1500 minutes'),
  ('32c0342e-01b0-771c-2d26-9e79b467170e', 'dbb96945-33e6-f0e9-820f-7ead273b4bd4', '76b52775-6d0c-4da4-f780-bdb155d54ffa', 'TEACHER', 'She did ask for you at nap time on Monday, but she was fine after a story.', now() - interval '1490 minutes'),
  ('aa5816fa-ea02-48ff-8ffc-bb00ecd3125d', 'd4b44f20-bab6-8a08-7513-a44c8c3276cd', '0ff2e40d-c01f-df7b-af75-6e65bb75a46b', 'PARENT', 'Salam, is there a school bus stop closer to Eglinton and Hurontario this year?', now() - interval '4300 minutes'),
  ('fb39fcfe-99e9-4641-3cc3-29b16a23328b', 'd4b44f20-bab6-8a08-7513-a44c8c3276cd', 'a01a2e53-2ed0-fbfe-51b2-f1b10c54f7af', 'ADMIN', 'Wa alaikum salam. Yes — the new stop is at Eglinton and Kennedy at 7:52 am. The office will send the updated route sheet home this week.', now() - interval '4100 minutes'),
  ('1748ffe1-ce17-3550-3705-8963afb08e57', '0ae207d7-4da0-81e5-a9a0-4feb736dd906', '8c124c87-330f-4d3b-17a1-a9ec6f9568d2', 'PARENT', 'Hello, Hadi was sick the day of Quiz 2. Is it possible to write it this week?', now() - interval '600 minutes'),
  ('67f25578-01d6-924b-6734-8bb6fc262fd5', '297b64f4-9478-44c2-577a-8fe9d7791dd4', 'e8e63c58-6491-ac0b-a921-2198b4f15822', 'PARENT', 'Ms. Saleh, Omar is finding fractions really hard and gets upset at homework time. Any tips?', now() - interval '5000 minutes'),
  ('bd6f540a-6870-9db4-d736-bb7b98ac0f08', '297b64f4-9478-44c2-577a-8fe9d7791dd4', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'Thanks for reaching out. Omar is trying hard! Fraction strips help a lot — I will send some home tomorrow, and Omar is welcome at extra help on Thursdays at lunch.', now() - interval '4800 minutes'),
  ('485f93c0-c661-e533-7c80-9daafdbc0568', '297b64f4-9478-44c2-577a-8fe9d7791dd4', 'e8e63c58-6491-ac0b-a921-2198b4f15822', 'PARENT', 'That is great, thank you.', now() - interval '4700 minutes'),
  ('1a64142d-9244-e078-2554-f8241eb3f119', '56f4b0c9-8fae-6098-c774-6ed9121ca1db', '5a4fb4b4-3a01-05aa-252f-d4e6660e0c9f', 'PARENT', 'We lost the permission form for the ROM trip. Can I sign something online instead?', now() - interval '3000 minutes'),
  ('aaf17448-8d7e-36dc-b6ae-cd62260aceef', '56f4b0c9-8fae-6098-c774-6ed9121ca1db', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'No problem — a message here is enough. I have marked Celine as allowed to go.', now() - interval '2900 minutes'),
  ('3f1e1e7b-cb64-5e2a-fcfa-e47322fdf341', '466f745a-6570-6b76-1548-0dd9536d745c', '3a990b82-fc9c-e0a1-755c-a70793304de5', 'STUDENT', 'Hi Ms. Saleh, can I hand in my descriptive paragraph tomorrow? I forgot my notebook at my grandma’s.', now() - interval '2000 minutes'),
  ('213674c7-17b9-6047-a410-e15ca5cf4ff8', '466f745a-6570-6b76-1548-0dd9536d745c', '24aaca9e-2f69-387d-bc30-098e705ce2d9', 'TEACHER', 'Yes, tomorrow is fine. Thank you for letting me know!', now() - interval '1900 minutes'),
  ('99f3ac07-d694-3ffa-91e6-7e95f09b1bff', '09a4135e-c1d5-b72f-8145-b206ca084dda', 'c8944cdb-458d-a1af-0403-12aea68364fb', 'PARENT', 'Mr. Barakat, when do we need the reference letter for the high school application?', now() - interval '8000 minutes'),
  ('a456ab61-5ff6-0369-d315-1b51fadea576', '09a4135e-c1d5-b72f-8145-b206ca084dda', '492150b0-571a-1d04-bc97-007b9e24194d', 'TEACHER', 'The deadline is December 4. I will have it ready by November 27.', now() - interval '7800 minutes'),
  ('cebb984e-75b6-5e79-a2c6-cb869ff62973', '18b75ecb-be17-9ff4-2acb-cbc6d1e3ad7a', '790543cf-db50-86ba-259c-cd62d4e59c82', 'PARENT', 'Just a reminder that Jafar has a peanut allergy — the class party on Friday has a lot of baked goods.', now() - interval '300 minutes'),
  ('3e18741f-9b24-b819-2435-c89bdef8763d', '644cf42e-c94a-d6a0-4d01-da9feff9ace4', '1b0681d4-787c-ce5d-8666-2303b9c0a958', 'STUDENT', 'Ms. Kassem, can I do the science fair project with a partner from the other class?', now() - interval '1200 minutes'),
  ('42211159-faee-3d6f-f39d-88c686a19242', '644cf42e-c94a-d6a0-4d01-da9feff9ace4', '10e5702d-d9fe-7fce-8be8-0ba4ffb45d7e', 'TEACHER', 'Partners have to be in our class this year, but you can work with anyone here. Let me know by Friday!', now() - interval '1100 minutes'),
  ('eac7a41f-6774-c2d4-d035-536ba8446f52', '20a19080-51b8-b3b7-2046-cc5aaaf87de5', '3a791ef6-3cf7-a7e2-f490-b9941ea86800', 'PARENT', 'I would love to help with the bake sale at the Fun Fair. Who should I talk to?', now() - interval '900 minutes'),
  ('d91f8f82-5a81-166a-92bc-6061c32776ff', '20a19080-51b8-b3b7-2046-cc5aaaf87de5', '0efacc5e-587c-ff55-52c4-fe346ce752dc', 'ADMIN', 'Thank you! I will add you to the bake sale list — we meet in the library at 1 pm that day.', now() - interval '850 minutes')
  ) v(id, conversation_id, sender_id, sender_role, body, created_at);
