-- This week's AI summaries for the Haddad children (the card in the parent portal).
INSERT INTO ai_weekly_summaries (student_id, week_start, content, model, generated_at)
SELECT v.student_id::uuid, date_trunc('week', ctx.today)::date, v.content, 'gpt-4o-mini', now() - interval '2 hours'
  FROM (VALUES
  ('83d8eb35-9a3e-9733-2f4f-d913684d23cc', 'Adam had a busy week in Grade 5. In Science, Adam''s lab write-up on states of matter came back with strong marks and helpful feedback, and Adam is partway through the Forces quiz. One Social Studies assignment (the community helpers chart) is still missing — a quick reminder at home would help. The To-do list shows what is coming up next.'),
  ('1815be2c-69ee-e380-33d8-4b51a6200ee9', 'Lina is off to a wonderful start in Grade 2. Recent spelling and reading marks are excellent, and Ms. Darwish moved Lina up a reading level this week. Keep up the nightly reading log — it is clearly paying off!')
  ) v(student_id, content) CROSS JOIN ctx;

COMMIT;
